<?php
declare(strict_types=1);
namespace Sentinel\Tests\Unit\Repositories;
use PDO;use PHPUnit\Framework\TestCase;use Sentinel\Core\Config;use Sentinel\Core\Database;use Sentinel\Core\RuntimeContext;use Sentinel\Repositories\IncidentRepository;
final class IncidentRepositoryTest extends TestCase {public function testIncidentQueriesHideOtherCompanies():void{$db=new Database(new Config(['database'=>[]]),static fn():PDO=>new PDO('sqlite::memory:',null,null,[PDO::ATTR_DEFAULT_FETCH_MODE=>PDO::FETCH_ASSOC]));$db->execute('CREATE TABLE incidents (incident_id INTEGER,incident_uuid TEXT,company_id INTEGER,site_id INTEGER,employee_id INTEGER,reporter_user_id INTEGER,shift_assignment_id INTEGER,patrol_session_id INTEGER,incident_number TEXT,incident_type TEXT,incident_category TEXT,severity TEXT,status TEXT,occurred_at TEXT,reported_at TEXT,description TEXT,actions_taken TEXT,resolution TEXT,closed_at TEXT,created_at TEXT,updated_at TEXT,deleted_at TEXT)');$db->execute("INSERT INTO incidents VALUES (1,'a',101,1,NULL,NULL,NULL,NULL,'A-1','SECURITY','ACCESS','LOW','OPEN','2026-09-14 08:00:00','2026-09-14 08:00:00','a',NULL,NULL,NULL,NULL,NULL,NULL),(2,'b',202,2,NULL,NULL,NULL,NULL,'B-1','SECURITY','ACCESS','LOW','OPEN','2026-09-14 08:00:00','2026-09-14 08:00:00','b',NULL,NULL,NULL,NULL,NULL,NULL)");$context=new RuntimeContext();$context->setTenantId(101);$repo=new IncidentRepository($db,$context);self::assertCount(1,$repo->listForCompany());self::assertNull($repo->findByIdForCompany('2'));}}